"""A compact parser for the jq expression language used by the CLI."""
from __future__ import annotations
from dataclasses import dataclass
import json
import re
from .diagnostics import CompileError

@dataclass(frozen=True)
class Filter:
    kind: str
    value: object = None
    children: tuple["Filter", ...] = ()

class Parser:
    def __init__(self, source: str) -> None:
        self.s = source; self.i = 0; self.t: list[tuple[str,object,int]] = []
        self.lex(); self.p = 0
    def lex(self) -> None:
        s=self.s; i=0
        while i<len(s):
            if s[i].isspace(): i+=1; continue
            if s[i]=='#':
                while i<len(s) and s[i]!='\n': i+=1
                continue
            if s[i]=='"':
                try: v,n=json.JSONDecoder().raw_decode(s[i:])
                except json.JSONDecodeError as e: raise CompileError("invalid string") from e
                self.t.append(('str',v,i)); i+=n; continue
            m=re.match(r'(?:-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?)',s[i:])
            if m:
                raw=m.group(); self.t.append(('num',json.loads(raw),i)); i+=len(raw); continue
            m=re.match(r'[A-Za-z_][A-Za-z_0-9]*',s[i:])
            if m:
                raw=m.group(); self.t.append(('id',raw,i)); i+=len(raw); continue
            found=False
            for op in ('//=', '...','..','?//','//','|=','+=','-=','*=','/=','==','!=','<=','>=','as','=>'):
                if s.startswith(op,i): self.t.append((op,op,i)); i+=len(op); found=True; break
            if found: continue
            if s[i] in '.[],{}():;|,+-*/%=<>?!@$': self.t.append((s[i],s[i],i)); i+=1; continue
            raise CompileError(f"unexpected character at position {i}")
        self.t.append(('EOF',None,len(s)))
    def peek(self,*ks:str)->bool: return self.t[self.p][0] in ks
    def pop(self,k:str|None=None):
        x=self.t[self.p]
        if k and x[0]!=k: raise CompileError(f"expected {k} at position {x[2]}")
        self.p+=1; return x
    def parse(self)->Filter:
        if self.peek('EOF'): raise CompileError('empty filter')
        x=self.expr(0)
        if not self.peek('EOF'): raise CompileError(f"unexpected token at position {self.t[self.p][2]}")
        return x
    def expr(self,minp:int)->Filter:
        left=self.primary()
        prec={',':1,'|':2,'?//':3,'//':4,'==':5,'!=':5,'<':5,'>':5,'<=':5,'>=':5,'+':6,'-':6,'*':7,'/':7,'%':7,'=':0,'|=':0,'+=':0,'-=':0}
        while self.t[self.p][0] in prec and prec[self.t[self.p][0]]>=minp:
            op=self.pop()[0]; p=prec[op]; right=self.expr(p+1)
            left=Filter('binary',op,(left,right))
        return left
    def primary(self)->Filter:
        k,v,pos=self.pop()
        if k=='EOF': raise CompileError('expected filter')
        if k=='.':
            x=Filter('identity')
            while True:
                if self.peek('id'):
                    name=self.pop()[1]; x=Filter('field',name,(x,))
                elif self.peek('.') and self.p+1 < len(self.t) and self.t[self.p+1][0]=='id':
                    self.pop(); name=self.pop()[1]; x=Filter('field',name,(x,))
                elif self.peek('['):
                    self.pop('[')
                    if self.peek(']'): self.pop(); x=Filter('iterate',(x,))
                    else:
                        a=None if self.peek(':') else self.expr(0); b=None
                        if self.peek(':'):
                            self.pop(); b=None if self.peek(']') else self.expr(0)
                            x=Filter('slice',(x,a,b))
                        else: x=Filter('index',(x,a,None))
                        self.pop(']')
                else: break
            return x
        if k in ('num','str'): return Filter('literal',v)
        if k=='id':
            if v in ('true','false','null'): return Filter('literal',{'true':True,'false':False,'null':None}[v])
            if v in ('empty','error'): return Filter(v)
            if self.peek('('):
                self.pop(); args=[]
                if not self.peek(')'):
                    while True:
                        args.append(self.expr(0))
                        if not self.peek(';',','): break
                        self.pop()
                self.pop(')'); return Filter('call',v,tuple(args))
            if v in {'length','keys','values','type','add','any','all','flatten','sort','unique','reverse','min','max','floor','ceil','abs','not','arrays','objects','iterables','scalars','booleans','nulls','strings','numbers','tojson','fromjson','tostring','tonumber','sqrt','empty'}:
                return Filter('call',v,())
            raise CompileError(f"unknown filter at position {pos}")
        if k=='[':
            items=[]
            if not self.peek(']'):
                while True:
                    items.append(self.expr(0))
                    if not self.peek(','): break
                    self.pop()
            self.pop(']'); return Filter('array',children=tuple(items))
        if k=='{':
            items=[]
            if not self.peek('}'):
                while True:
                    key=self.pop()
                    if key[0] not in ('id','str'): raise CompileError('invalid object key')
                    self.pop(':'); items.append((str(key[1]),self.expr(0)))
                    if not self.peek(','): break
                    self.pop()
            self.pop('}'); return Filter('object',items)
        if k=='(':
            x=self.expr(0); self.pop(')'); return x
        if k=='-': return Filter('unary','-',(self.primary(),))
        if k=='.' and self.peek('..'): return Filter('recurse')
        raise CompileError(f"expected filter at position {pos}")

def parse(program:str)->Filter: return Parser(program).parse()
