    if op=='//': return a if is_truthy(a) else b
    if op in ('==','!=','<','>','<=','>='): return {'==':a==b,'!=':a!=b,'<':a<b,'>':a>b,'<=':a<=b,'>=':a>=b}[op]
    if op=='+':
        if isinstance(a,dict) and isinstance(b,dict): return {**a,**b}
        if isinstance(a,list) and isinstance(b,list): return a+b
        return a+b
    if op=='-': return a-b if isinstance(a,(int,float)) else [x for x in a if x not in b]
    if op=='*': return a*b
